import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] all = System.in.readAllBytes();
        int nl = 0;
        while (all[nl] != '\n') nl++;
        long n = Long.parseLong(new String(all, 0, nl).trim());
        int end = all.length;
        if (end > nl + 1 && all[end - 1] == '\n') end--;
        String cs = "bcdfghjklmnpqrstvwxyz";
        long cnt = 0;
        for (int i = nl + 1; i < end; i++) {
            int c = all[i];
            boolean upper = c >= 'A' && c <= 'Z';
            if (!upper && !(c >= 'a' && c <= 'z')) continue;
            char lower = (char) (c | 0x20);
            if ("aeiou".indexOf(lower) >= 0 || ++cnt % n != 0) continue;
            // Shift to the next consonant (z wraps to b), keeping the case.
            char x = cs.charAt((cs.indexOf(lower) + 1) % cs.length());
            all[i] = (byte) (upper ? Character.toUpperCase(x) : x);
        }
        BufferedOutputStream out = new BufferedOutputStream(System.out);
        out.write(all, nl + 1, end - nl - 1);
        out.write('\n');
        out.flush();
    }
}

package main

import (
	"bytes"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	all, _ := io.ReadAll(os.Stdin)
	nl := bytes.IndexByte(all, '\n')
	n, _ := strconv.Atoi(strings.TrimSpace(string(all[:nl])))
	word := bytes.TrimSuffix(all[nl+1:], []byte("\n"))
	const cs = "bcdfghjklmnpqrstvwxyz"
	cnt := 0
	for i, c := range word {
		upper := c >= 'A' && c <= 'Z'
		if !upper && !(c >= 'a' && c <= 'z') {
			continue
		}
		lower := c | 0x20
		if strings.IndexByte("aeiou", lower) >= 0 {
			continue
		}
		if cnt++; cnt%n == 0 {
			// Shift to the next consonant (z wraps to b), keeping the case.
			x := cs[(strings.IndexByte(cs, lower)+1)%len(cs)]
			if upper {
				x -= 'a' - 'A'
			}
			word[i] = x
		}
	}
	os.Stdout.Write(append(word, '\n'))
}
